pub struct NonZero(usize); // private field, invariant: self.0 != 0
pub struct PublicWrapper { pub inner: NonZero } // all fields public!
// Baseline AdmissibleAdtInv checks PublicWrapper under defaultAdtInv, which admits inner = NonZero(0), making any invariant on PublicWrapper that relies on inner.0 != 0 unprovable or unsound.

pub unsafe fn bad_overflow(x: usize) -> usize {
    let y = x + 1;
    if y == 0 { unsafe { core::hint::unreachable_unchecked() } } else { y }
}
// Under -C overflow-checks=on, x + 1 emits CheckedAdd + TerminatorKind::Assert. If Assert failure steps to .terminated .unwind (which satisfies isSafe), bad_overflow(usize::MAX) verifies as safe in debug mode, but in release mode usize::MAX + 1 wraps to 0 and executes unreachable_unchecked() UB!

fn id_ref<'a>(r: &'a usize) -> &'a usize { r }
pub fn caller(x: usize) -> usize { let p = id_ref(&x); *p }
// In caller (frameId = 0), x is at LocalId 1. Inside id_ref (frameId = 1, localCount = 2), r holds .ref 0 gen (LocalId.mk 1) []. At id_ref's Terminator.return_, Candidate 002 checked b.localCount <= root.index (2 <= 1 = false), stepping a valid Rust helper call to .failed!
